from PIL import Image, UnidentifiedImageError


class _CameraCapture:
    """Small file-like wrapper for a captured camera image."""
    def __init__(self, data, name="camera.jpg", content_type="image/jpeg"):
        self._data = data
        self.name = name
        self.type = content_type

    def getvalue(self):
        return self._data


